package dev.homecontrol.app;
import org.json.*;
import java.io.IOException;

/** Exact camera RPC whitelist. NAS credentials stay in the current sheet's memory. */
final class CameraNas {
 static String method(String model,String operation)throws IOException{if(!CameraPolicy.supported(model))throw new IOException("此型号尚未适配 NAS");switch(operation){case "camera.nas.get":return "nas_get_config";case "camera.nas.scan":return "nas_scan";case "camera.nas.list":return "nas_list_dir";case "camera.nas.set":return "nas_set_config";default:throw new IOException("不支持的 NAS 操作");}}
 static JSONObject share(JSONObject input)throws Exception{JSONObject out=new JSONObject();Object type=input.opt("type"),address=input.opt("addr");if(!(type instanceof Number)||!(address instanceof Number)||((Number)type).intValue()<0||((Number)type).intValue()>255||((Number)address).longValue()<0||((Number)address).longValue()>0xffffffffL)throw new IOException("NAS 地址信息无效，请重新搜索");out.put("type",type).put("addr",address);for(String key:new String[]{"group","name","dir","user","pass"}){Object value=input.opt(key);if(!(value instanceof String)||((String)value).length()>512||((String)value).contains("\u0000"))throw new IOException("NAS 连接参数无效");out.put(key,value);}return out;}
 static Object params(String operation,JSONObject input)throws Exception{switch(operation){case "camera.nas.get":return new JSONObject();case "camera.nas.scan":return new JSONArray();case "camera.nas.list":return new JSONObject().put("share",share(input.getJSONObject("share")));case "camera.nas.set":int state=input.getInt("state"),interval=input.getInt("sync_interval"),retention=input.getInt("video_retention_time");if(state<1||state>3||interval<1||interval>86400||retention<1||retention>31536000)throw new IOException("NAS 存储参数无效");JSONObject share=share(input.getJSONObject("share"));if(share.getString("dir").trim().isEmpty())throw new IOException("请选择存储目录");return new JSONObject().put("state",state).put("sync_interval",interval).put("video_retention_time",retention).put("share",share);default:throw new IOException("NAS 操作无效");}}
 static JSONObject config(Object value)throws Exception{if(value instanceof JSONObject){JSONObject result=(JSONObject)value;if(result.has("state")&&result.has("sync_interval")&&result.has("video_retention_time"))return result;Object nested=result.opt("result");if(nested!=null&&nested!=value)return config(nested);}if(value instanceof JSONArray&&((JSONArray)value).length()==1)return config(((JSONArray)value).get(0));throw new IOException("摄像机未返回可用的 NAS 配置");}
 static JSONArray servers(Object value){if(value instanceof JSONArray)return (JSONArray)value;if(value instanceof JSONObject){JSONObject o=(JSONObject)value;for(String key:new String[]{"result","list","servers","dirs"}){Object nested=o.opt(key);if(nested!=null){JSONArray found=servers(nested);if(found.length()>0)return found;}}}return new JSONArray();}
}
